mapper.select:
SELECT
  /* 1. 오늘 방문자 수 (중복 IP 제외) */
  (SELECT COUNT(DISTINCT CLIENT_IP)
   FROM VISITOR_HISTORY
   WHERE VISIT_STORY_MEM_ID = #{memId}
     AND REG_DATE_INQUIRY = DATE_FORMAT(NOW(), '%Y%m%d')
  )                                    AS TODAY_VISIT_CNT,

  /* 2. 이번 주 방문자 수 (최근 7일간, 일자별 중복 제외 합산) */
  (SELECT COUNT(A.CNT)
   FROM (
          SELECT COUNT(*) AS CNT
          FROM VISITOR_HISTORY
          WHERE VISIT_STORY_MEM_ID = #{memId}
            AND REG_DATE_INQUIRY BETWEEN DATE_FORMAT(DATE_ADD(NOW(), INTERVAL -6 DAY), '%Y%m%d')
            AND DATE_FORMAT(NOW(), '%Y%m%d')
          GROUP BY REG_DATE_INQUIRY, CLIENT_IP
        ) A
  )                                    AS WEEKLY_VISIT_CNT,

  /* 3. 한 달 방문자 수 (최근 30일간, 일자별 중복 제외 합산) */
  (SELECT COUNT(B.CNT)
   FROM (
          SELECT COUNT(*) AS CNT
          FROM VISITOR_HISTORY
          WHERE VISIT_STORY_MEM_ID = #{memId}
            AND REG_DATE_INQUIRY BETWEEN DATE_FORMAT(DATE_ADD(NOW(), INTERVAL -29 DAY), '%Y%m%d')
            AND DATE_FORMAT(NOW(), '%Y%m%d')
          GROUP BY REG_DATE_INQUIRY, CLIENT_IP
        ) B
  )                                    AS MONTHLY_VISIT_CNT,

  /* 4. 전체 누적 방문자 수 */
  (SELECT COUNT(C.CNT)
   FROM (
          SELECT COUNT(*) AS CNT
          FROM VISITOR_HISTORY
          WHERE VISIT_STORY_MEM_ID = #{memId}
          GROUP BY REG_DATE_INQUIRY, CLIENT_IP
        ) C
  )                                    AS CUMULATIVE_VISIT_CNT,

  DATE_FORMAT(NOW(), '%Y-%m-%d %H:%i') AS VISIT_STATIS_CRITERIA
FROM DUAL

