INSERT INTO VISITOR_HISTORY( ACCESS_PATH
                           , ACCESS_TARGET
                           , ACC_PAGE_URL
                           , CLIENT_IP
                           , CLIENT_ID
                           , CALL_SERVICE
                           , VISIT_STORY_MEM_ID
                           , REG_MONTH_INQUIRY
                           , REG_DATE_INQUIRY
                           , REG_DATE)
VALUES ( #{accessPath}
       , #{accessTarget}
       , #{accPageUrl}
       , #{clientIp}
       , #{clientId}
       , #{callService}
       , #{visitStoryMemId}
       , #{regMonthInquiry}
       , #{regDateInquiry}
       , NOW())
